const body = $input.first().json.body;

function normalizarTexto(valor) {
  if (typeof valor !== 'string') return valor;
  return valor.trim().replace(/\s+/g, ' ');
}

let tipo = body.tipo_trabajo;
if (typeof tipo === 'string') {
  tipo = tipo.trim();
}
if (!tipo) {
  tipo = 'Sin especificar';
}
body.tipo_trabajo = tipo;

let estadoEquipo = body.estado_equipo;
if (typeof estadoEquipo === 'string') {
  estadoEquipo = estadoEquipo.trim();
}
if (!estadoEquipo) {
  estadoEquipo = 'Nuevo';
}
body.estado_equipo = estadoEquipo;

body.equipo = normalizarTexto(body.equipo);
body.modelo = normalizarTexto(body.modelo);

let nivelDificultad = body.nivel_dificultad;
if (nivelDificultad === undefined || nivelDificultad === null || nivelDificultad === '') {
  nivelDificultad = 1;
} else {
  nivelDificultad = Number(nivelDificultad);
  if (isNaN(nivelDificultad)) {
    nivelDificultad = 1;
  }
}
body.nivel_dificultad = nivelDificultad;

let emailCliente = body.Email_Cliente;
if (typeof emailCliente === 'string') {
  emailCliente = emailCliente.trim();
} else {
  emailCliente = '';
}
body.Email_Cliente = emailCliente;

return [{ json: { body } }];

const item = $input.first().json;
const cliente = item.fields.cliente;

let lista;
if (cliente === 'GE') {
  lista = 'GE';
} else if (cliente === 'Tecnoimagen') {
  lista = 'Tecnoimagen';
} else {
  lista = 'General';
}

item.lista_precios = lista;

return [{ json: item }];

const item = $input.first().json;

function limpiarDireccion(direccion) {
  if (!direccion) return direccion;
  return direccion
    .replace(/,?\s*(c\.?p\.?|c[oó]digo postal)\s*:?\s*\d+/gi, '')
    .replace(/\s*,\s*,/g, ',')
    .replace(/,\s*$/, '')
    .trim();
}

const origenLimpia = limpiarDireccion(item.fields.direccion_origen);
const destinoLimpia = limpiarDireccion(item.fields.direccion_destino);

item.direccion_origen_limpia = origenLimpia;
item.direccion_destino_limpia = destinoLimpia;
item.direccion_origen_calle = origenLimpia.split(',')[0].trim();
item.direccion_destino_calle = destinoLimpia.split(',')[0].trim();

return [{ json: item }];

const destinoRaw = $input.first().json; // respuesta cruda de "Geocodificar destino"
const limpio = $('Limpiar direcciones').item.json;
const base = $('Limpiar direcciones').item.json; // registro completo (id + fields) — funciona en el camino normal y en el de reintento, porque "Limpiar direcciones" es el nodo común inmediato anterior en ambos casos

function quitarAcentos(texto) {
  return texto.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function extraerAltura(calle) {
  const match = calle.match(/(\d+)(?!.*\d)/);
  return match ? match[1] : null;
}

function primeraPalabraClave(calle) {
  const genericas = ['av', 'av.', 'avenida', 'calle', 'pasaje'];
  return quitarAcentos(calle)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(p => p.length > 2 && !genericas.includes(p) && isNaN(p))[0] || null;
}

function primeraPalabraClaveLocalidad(localidad) {
  if (!localidad) return null;
  return quitarAcentos(localidad)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(p => p.length > 2)[0] || null;
}

// Alias para abreviaturas que el geocodificador no reconoce literalmente
const ALIAS_LOCALIDAD = {
  caba: ['buenos aires', 'ciudad autonoma', 'autonomous city'],
};

function localidadCoincide(palabraLocalidad, camposLocalidadTexto) {
  if (!palabraLocalidad) return true; // no hay nada que validar
  if (camposLocalidadTexto.includes(palabraLocalidad)) return true;
  const alias = ALIAS_LOCALIDAD[palabraLocalidad];
  if (alias) {
    return alias.some(a => camposLocalidadTexto.includes(a));
  }
  return false;
}

// Direcciones fijas conocidas, que no dependen del geocodificador externo
const DIRECCIONES_CONOCIDAS = [
  {
    patron: /diagonal\s*78.*1337|deposito sechi/i,
    lon: -58.530634,
    lat: -34.548926,
    nombre: 'Depósito Sechi (San Andrés)'
  }
];

function buscarDireccionConocida(calleOriginal) {
  const normalizada = quitarAcentos(calleOriginal).toLowerCase();
  return DIRECCIONES_CONOCIDAS.find(d => d.patron.test(normalizada)) || null;
}

function resolverDireccion(calleOriginal, localidadOriginal, features) {
  const conocida = buscarDireccionConocida(calleOriginal);
  if (conocida) {
    return { valido: true, lon: conocida.lon, lat: conocida.lat };
  }

  if (!features || features.length === 0) {
    return { valido: false, lon: null, lat: null };
  }

  const props = features[0].properties;

  const alturaEsperada = extraerAltura(calleOriginal);
  const alturaObtenida = props.housenumber;
  if (alturaEsperada && alturaObtenida && alturaEsperada !== alturaObtenida) {
    return { valido: false, lon: null, lat: null };
  }

  const palabraClave = primeraPalabraClave(calleOriginal);
  const calleObtenida = quitarAcentos(props.street || props.name || '').toLowerCase();
  if (palabraClave && !calleObtenida.includes(palabraClave)) {
    return { valido: false, lon: null, lat: null };
  }

  const palabraLocalidad = primeraPalabraClaveLocalidad(localidadOriginal);
  const camposLocalidad = quitarAcentos(
    [props.locality, props.region, props.county, props.borough, props.macrocounty, props.neighbourhood]
      .filter(Boolean)
      .join(' ')
  ).toLowerCase();
  if (!localidadCoincide(palabraLocalidad, camposLocalidad)) {
    return { valido: false, lon: null, lat: null };
  }

  const coords = features[0].geometry.coordinates;
  return { valido: true, lon: coords[0], lat: coords[1] };
}

const origenFeatures = $('Geodecodificar origen').item.json.features;
const destinoFeatures = destinoRaw.features;

const origenLocalidad = limpio.direccion_origen_limpia.split(',')[1]?.trim();
const destinoLocalidad = limpio.direccion_destino_limpia.split(',')[1]?.trim();

const origen = resolverDireccion(limpio.direccion_origen_calle, origenLocalidad, origenFeatures);
const destino = resolverDireccion(limpio.direccion_destino_calle, destinoLocalidad, destinoFeatures);

return [{
  json: {
    ...base,
    geocoding_valido: origen.valido && destino.valido,
    origen_lon: origen.lon,
    origen_lat: origen.lat,
    destino_lon: destino.lon,
    destino_lat: destino.lat
  }
}];

const base = $('Val').item.json; // registro completo: id, fields, origen/destino lon/lat
const ruta = $input.first().json; // respuesta de "Calcular ruta"

const kmIda = ruta.routes[0].summary.distance; // ya viene en km, porque pedimos "units": "km"
const kmIdaYVuelta = kmIda * 2;

return [{
  json: {
    ...base,
    km_calculados: kmIdaYVuelta
  }
}];

const item = $input.first().json;
const equipo = item.fields.equipo;
const modelo = item.fields.modelo;

let equipoBusqueda = equipo;

if (equipo === 'Resonador' && modelo) {
  equipoBusqueda = `Resonador - ${modelo}`;
}

return [{
  json: {
    ...item,
    equipo_busqueda: equipoBusqueda
  }
}];

const item = $input.first().json;
const equipo = item.fields.equipo;
const modelo = item.fields.modelo;

let equipoBusqueda = equipo;

if ((equipo === 'Resonador' || equipo === 'Mamografo') && modelo) {
  equipoBusqueda = `${equipo} - ${modelo}`;
}

return [{
  json: {
    ...item,
    equipo_busqueda: equipoBusqueda
  }
}];

const precioRow = $input.first().json;
const nivel = Number($('Switch lista de precios').item.json.fields['Nivel de Dificultad']);

let campoPrecio;
if (nivel <= 0) {
  campoPrecio = 'Dificultad_0_USD';
} else if (nivel === 1) {
  campoPrecio = 'Dificultad_1_USD';
} else if (nivel === 2) {
  campoPrecio = 'Dificultad_2_USD';
} else if (nivel === 3 || nivel === 4) {
  campoPrecio = 'Dificultad_3_y_4_USD';
} else {
  campoPrecio = 'dificultad nivel 5';
}

const precio = precioRow.fields[campoPrecio];

return [{
  json: {
    ...precioRow,
    precio_rigging_resuelto: precio,
    campo_precio_usado: campoPrecio
  }
}];

const item = $input.first().json;

const ACOPLADO_PATENTE = 'AG 366 KC';

let patentes = item.fields['Patente (from vehiculo)'] ?? [];
if (!Array.isArray(patentes)) {
  patentes = [patentes];
}

const requiereAcoplado = patentes.includes(ACOPLADO_PATENTE);
const vehiculosCandidatos = patentes.filter(p => p !== ACOPLADO_PATENTE);

return [{
  json: {
    ...item,
    vehiculos_candidatos: vehiculosCandidatos,
    requiere_acoplado: requiereAcoplado,
    acoplado_patente: requiereAcoplado ? ACOPLADO_PATENTE : null,
    acoplado_sin_tractor: requiereAcoplado && vehiculosCandidatos.length === 0
  }
}];

const item = $input.first().json; // fila de precio + vehiculos_candidatos, etc.
const presupuesto = $('Switch lista de precios').item.json; // id + fields del presupuesto — nodo común a los 4 caminos (normal, Reintentar direcciones, Reintentar vehiculo, Reintentar cotizacion manual)

const esGE = presupuesto.fields['Lista de precios aplicada'] === 'GE';

const valorRiggingCalculado = esGE
  ? item.precio_rigging_resuelto
  : item.fields['Precio rigging'];

const monedaRiggingCalculada = esGE ? 'USD' : 'ARS';

// Solo cuando este reintento viene específicamente de "Reintentar cotizacion manual",
// el valor cargado a mano gana por sobre el resultado de la búsqueda. Cualquier otro
// camino (incluido Reintentar vehiculo, que también puede pasar dos veces por acá)
// recalcula como siempre, sin cambios de comportamiento.
const esReintentoDeCotizacion = presupuesto.fields['Status'] === 'Reintentar cotizacion manual';

const valorRigging = esReintentoDeCotizacion ? presupuesto.fields['Valor de Rigging'] : valorRiggingCalculado;
const monedaRigging = esReintentoDeCotizacion ? (presupuesto.fields['Moneda Rigging'] || monedaRiggingCalculada) : monedaRiggingCalculada;

return [{
  json: {
    ...item,
    presupuesto_id: presupuesto.id,
    valor_rigging_resuelto: valorRigging,
    moneda_rigging_resuelta: monedaRigging
  }
}];

const previo = $('Unificar Valor de Rigging').item.json; // antes de que el Update de Airtable "limpiara" el ítem
const presupuesto = $('Switch lista de precios').item.json; // id + fields completos, incluye Km calculados y fecha_propuesta — nodo común a los 3 caminos (normal, Reintentar direcciones, Reintentar vehiculo)

const KM_POR_DIA = 800;

const kmIda = presupuesto.fields['Km calculados'] / 2; // Km calculados es ida y vuelta
const diasViaje = Math.max(1, Math.ceil(kmIda / KM_POR_DIA));
const diasTrabajo = 1;

const fechaTrabajo = new Date(presupuesto.fields.fecha_propuesta);

function sumarDias(fecha, dias) {
  const nueva = new Date(fecha);
  nueva.setDate(nueva.getDate() + dias);
  return nueva;
}

function formatoFecha(fecha) {
  return fecha.toISOString().split('T')[0]; // YYYY-MM-DD
}

const fechaInicio = sumarDias(fechaTrabajo, -diasViaje);
const fechaFin = sumarDias(fechaTrabajo, diasViaje + diasTrabajo - 1);

return [{
  json: {
    ...previo,
    cliente_nombre: presupuesto.fields.cliente,
    equipo_nombre: presupuesto.fields.equipo,
    dias_viaje: diasViaje,
    fecha_inicio_ocupacion: formatoFecha(fechaInicio),
    fecha_fin_ocupacion: formatoFecha(fechaFin)
  }
}];

const eventos = $input.all().map(i => i.json);
const previo = $('Calcular ventana de disponibilidad').item.json;
const candidatos = previo.vehiculos_candidatos;
const requiereAcoplado = previo.requiere_acoplado;
const acopladoPatente = previo.acoplado_patente;

function patenteOcupada(patente) {
  return eventos.some(ev => (ev.summary || '').includes(patente));
}

// El acoplado es un recurso único: si el caso lo requiere y está ocupado,
// ningún tractor candidato sirve, porque todos dependen del mismo acoplado.
const acopladoLibre = !requiereAcoplado || !patenteOcupada(acopladoPatente);

const vehiculoLibre = acopladoLibre
  ? (candidatos.find(p => !patenteOcupada(p)) || null)
  : null;

return [{
  json: {
    ...previo,
    vehiculo_libre: vehiculoLibre,
    hay_vehiculo_disponible: vehiculoLibre !== null
  }
}];

const item = $input.first().json;

const patentesAReservar = item.requiere_acoplado
  ? [item.vehiculo_libre, item.acoplado_patente]
  : [item.vehiculo_libre];

return patentesAReservar.map(patente => ({
  json: {
    ...item,
    patente_a_reservar: patente
  }
}));

const eventos = $input.all();
const reservas = $('Armar reservas').all();

const items = eventos.map((evento, i) => ({
  ...reservas[i].json,
  evento_calendario_id: evento.json.id
}));

const tractorItem = items.find(it => it.patente_a_reservar === it.vehiculo_libre);

return [{ json: tractorItem }];

const resuelto = $('Resolver disponibilidad').item.json;
const kmCalculados = Number($('Switch lista de precios').item.json.fields['Km calculados']);
const listaPrecios = $('Switch lista de precios').item.json.fields['Lista de precios aplicada'];

const KM_UMBRAL = 150;
const esGE = listaPrecios === 'GE';

let conceptosNecesarios;
if (kmCalculados <= KM_UMBRAL) {
  conceptosNecesarios = ['Flete Local'];
} else {
  conceptosNecesarios = esGE ? ['Flete Local', 'Flete por Km'] : ['Flete por Km'];
}

return [{
  json: {
    ...resuelto,
    km_calculados_flete: kmCalculados,
    lista_precios_flete: listaPrecios,
    conceptos_necesarios: conceptosNecesarios
  }
}];

const filas = $input.all().map(i => i.json);
const datos = $('Calcular concepto de flete').item.json;

const { requiere_acoplado, acoplado_patente, vehiculo_libre, km_calculados_flete, lista_precios_flete, presupuesto_id } = datos;

const esGE = lista_precios_flete === 'GE';
const esTecno = lista_precios_flete === 'Tecnoimagen';

function esFilaDelVehiculo(fila) {
  const esCamionDeApoyo = (fila.fields['Lista'] || '').toLowerCase().includes('apoyo');
  if (esCamionDeApoyo) return false; // excluye camión de apoyo (fuera de alcance de este nodo)
  const patentes = fila.fields['Patente (from vehiculo)'] ?? [];
  if (requiere_acoplado) {
    return patentes.includes(acoplado_patente);
  }
  return patentes.length === 1 && patentes[0] === vehiculo_libre;
}

const filasElegidas = esTecno ? filas : filas.filter(esFilaDelVehiculo);

const valorFlete = filasElegidas.reduce((total, fila) => {
  const esPorKm = fila.fields['Concepto'] === 'Flete por Km';
  const precio = fila.fields['Precio'];
  return total + (esPorKm ? precio * km_calculados_flete : precio);
}, 0);

const monedaFlete = esGE ? 'USD' : 'ARS';

return [{
  json: {
    ...datos,
    valor_flete_resuelto: valorFlete,
    moneda_flete_resuelta: monedaFlete
  }
}];

function leer(nombreNodo, campoValor, campoMoneda) {
  try {
    const n = $(nombreNodo).item.json;
    return { valor: n[campoValor], moneda: n[campoMoneda], fuente: n };
  } catch (e) {
    return null; // ese nodo no se ejecutó en este camino
  }
}

const actual = $input.first().json; // único dato garantizado en los 5 caminos (puede venir "reseteado" por un Update de Airtable)

const rigging = leer('Unificar Valor de Rigging', 'valor_rigging_resuelto', 'moneda_rigging_resuelta')
  || { valor: actual.valor_rigging_resuelto, moneda: actual.moneda_rigging_resuelta };

const flete = leer('Unificar Valor de Flete', 'valor_flete_resuelto', 'moneda_flete_resuelta');

// Para el spread final preferimos el objeto completo de "Unificar Valor de Flete" (tiene presupuesto_id
// y todos los campos acumulados de la cadena) cuando existe; si no corrió (Reintentar moneda), el propio
// item de entrada ya trae presupuesto_id puesto por "Preparar reintento de moneda".
const base = flete ? flete.fuente : actual;
const valorFlete = flete ? flete.valor : actual.valor_flete_resuelto;
const monedaFlete = flete ? flete.moneda : actual.moneda_flete_resuelta;

const monedasCoinciden = rigging.moneda === monedaFlete;

return [{
  json: {
    ...base,
    monedas_coinciden: monedasCoinciden,
    valor_total_resuelto: monedasCoinciden
      ? (rigging.valor + valorFlete)
      : null
  }
}];

const item = $input.first().json; // registro completo de Airtable (id + fields), con los valores de moneda ya corregidos a mano

return [{
  json: {
    ...item,
    presupuesto_id: item.id,
    valor_rigging_resuelto: item.fields['Valor de Rigging'],
    moneda_rigging_resuelta: item.fields['Moneda Rigging'],
    valor_flete_resuelto: item.fields['Valor de Flete'],
    moneda_flete_resuelta: item.fields['Moneda flete']
  }
}];

// Respuesta de "actualiza valor total": { id, fields: {...} }
const item = $input.first().json;
const necesitaTerceros = item.fields['Necesita Terceros']; // vacío, 'SI' o 'NO'
const yaResuelto = necesitaTerceros === 'SI' || necesitaTerceros === 'NO';

return [{
  json: {
    ...item,
    ya_resuelto_terceros: yaResuelto
  }
}];

