const item = $input.first().json;
const fields = item.fields;

const necesitaTerceros = fields['Necesita Terceros'];
const valorTotalActual = Number(fields['Valor Total']) || 0;
const valorTerceros = Number(fields['Valor de Terceros']) || 0;
const valorDiaTrabajo = Number(fields['Valor Dia de Trabajo']) || 0;
const valorDesconsolidado = Number(fields['Valor Desconsolidado']) || 0;
const valorMontajeExtendido = Number(fields['Valor Montaje Extendido']) || 0;
const valorCamionApoyo = fields['Camion de apoyo aplicado'] ? (Number(fields['Valor Camion de apoyo']) || 0) : 0;

const sumaTerceros = necesitaTerceros === 'SI' ? valorTerceros : 0;

const valorTotalFinal = valorTotalActual + sumaTerceros + valorDiaTrabajo + valorDesconsolidado + valorMontajeExtendido + valorCamionApoyo;

return [{
  json: {
    presupuesto_id: item.id,
    valor_total_resuelto: valorTotalFinal,
    fecha_propuesta: fields['fecha_propuesta']
  }
}];

const item = $input.first().json;
const fields = item.fields;

// Saca los puntos de las direcciones para no romper los regex de PE7
// (que cortan "Destino: ... ." en el primer punto que encuentran — ej. "Av.")
function limpiar(direccion) {
  if (!direccion) return '';
  return direccion.replace(/\./g, '');
}

const origenLimpio = limpiar(fields['direccion_origen']);
const destinoLimpio = limpiar(fields['direccion_destino']);
const vehiculo = (fields['Patente (from flota)'] || []).join(', ');
const terceros = fields['Necesita Terceros'] === 'SI'
  ? ` Incluye contratación de terceros: ${fields['Concepto de Terceros'] || ''}.`
  : '';

const ideaSemilla =
  `Presupuesto de traslado para ${fields['equipo']} ${fields['modelo'] || ''} (${fields['Email_Cliente']}). ` +
  `Cliente: ${fields['cliente']}. ` +
  `Equipo: ${fields['equipo']}. ` +
  `Origen: ${origenLimpio}. ` +
  `Destino: ${destinoLimpio}. ` +
  `Fecha propuesta: ${fields['fecha_propuesta'] || 'a confirmar'}. ` +
  `Tipo de trabajo: ${fields['Tipo de trabajo'] || ''}. ` +
  `Vehículo asignado: ${vehiculo}.` +
  terceros + ` ` +
  `Valor Total: $${fields['Valor Total']} ${fields['Moneda Rigging'] || ''}.`;

return [{
  json: {
    presupuesto_id: item.id,
    idea_semilla: ideaSemilla
  }
}];

