const necesitaVisita = item['Necesita Visita'];
const valorTerceros = item['Valor de Terceros'];

const faltaDecisionTerceros = necesitaTerceros === 'SI' && (valorTerceros === undefined || valorTerceros === null || valorTerceros === '' || Number(valorTerceros) <= 0);

// NUEVO: la visita ya no entra en "datos_completos" de terceros — tiene su propia señal
const requiereEsperarVisita = necesitaVisita === 'SI';

const datosCompletos = !faltaDecisionTerceros;

const datos = {
  presupuesto_id: item['ID de Presupuesto'],
  necesita_terceros: necesitaTerceros,
  valor_terceros: valorTerceros,
