const eventos = $input.all().map(i => i.json);
const datos = $('Procesar decisión de terceros').item.json;

const fecha = new Date(datos.fecha_propuesta);
const diaSemana = fecha.getUTCDay(); // 0 = domingo, 6 = sábado
const esFinDeSemana = diaSemana === 0 || diaSemana === 6;

const FERIADOS_2026 = [
  '2026-01-01', '2026-02-16', '2026-02-17', '2026-03-23', '2026-03-24',
  '2026-04-02', '2026-04-03', '2026-05-01', '2026-05-25', '2026-06-15',
  '2026-07-09', '2026-07-10', '2026-08-17', '2026-10-12', '2026-11-09',
  '2026-11-23', '2026-12-07', '2026-12-08', '2026-12-25'
];
const fechaStr = datos.fecha_propuesta.slice(0, 10); // YYYY-MM-DD
const esFeriadoNacional = FERIADOS_2026.includes(fechaStr);

const esFeriadoCalendario = eventos.some(ev => (ev.summary || '').trim().toUpperCase() === 'FERIADO');

const aplicaRecargo = esFinDeSemana || esFeriadoNacional || esFeriadoCalendario;

const valorTotalConRecargo = aplicaRecargo
  ? Math.round(datos.valor_total_resuelto * 1.10)
  : datos.valor_total_resuelto;

return [{
  json: {
    presupuesto_id: datos.presupuesto_id,
    valor_total_resuelto: valorTotalConRecargo
  }
}];

