const item = $input.first().json; // { id, createdTime, fields } — viene directo de la entrada
const f = item.fields;

function pad2(n) { return String(n).padStart(2, '0'); }

function fechaDMY(valor) {
  const d = new Date(valor);
  return {
    dia: pad2(d.getUTCDate()),
    mes: pad2(d.getUTCMonth() + 1),
    anio: String(d.getUTCFullYear())
  };
}

function formatoMonto(valor) {
  const n = Number(valor) || 0;
  return n.toLocaleString('es-AR', { maximumFractionDigits: 2 });
}

function formatoKm(valor) {
  const n = Number(valor) || 0;
  return n.toLocaleString('es-AR', { maximumFractionDigits: 1 });
}

function primerValor(valor) {
  if (Array.isArray(valor)) return valor[0] || '';
  return valor || '';
}

const fechaRecepcion = fechaDMY(item.createdTime);
const fechaEnvio = fechaDMY(new Date().toISOString());
const fechaEntrega = fechaDMY(f['fecha_propuesta']);

const kmIdaYVuelta = Number(f['Km calculados']) || 0;
const kmIda = kmIdaYVuelta / 2;

const valorTerceros = f['Necesita Terceros'] === 'SI' ? (Number(f['Valor de Terceros']) || 0) : 0;
const valorDiaTrabajo = Number(f['Valor Dia de Trabajo']) || 0;
const valorDesconsolidado = Number(f['Valor Desconsolidado']) || 0;
const valorMontajeExtendido = Number(f['Valor Montaje Extendido']) || 0;
const valorCamionApoyo = f['Camion de apoyo aplicado'] ? (Number(f['Valor Camion de apoyo']) || 0) : 0;
const adicionales = valorTerceros + valorDiaTrabajo + valorDesconsolidado + valorMontajeExtendido + valorCamionApoyo;

const datos = {
  presupuesto_id: item.id,

  FECHA_DIA: fechaRecepcion.dia,
  FECHA_MES: fechaRecepcion.mes,
  FECHA_ANIO: fechaRecepcion.anio,

  PRESUPUESTO_NRO: String(f['Nº de Presupuesto'] ?? ''),
  NUMERO_FACTURA: '',

  FECHA_MAIL_DIA: fechaEnvio.dia,
  FECHA_MAIL_MES: fechaEnvio.mes,

  ESTADO: '',
  DIREC_MAIL: f['Email_Cliente'] || '',

  EMPRESA: f['cliente'] || '',
  DIRECCION_RETIRO: f['direccion_origen'] || '',
  DIRECCION_DESTINO: f['direccion_destino'] || '',
  PRODUCTO: f['equipo'] || '',
  MARCA: '',
  MODELO: f['modelo'] || '',
  CEL: '',
  FECHA_ENTREGA_DIA: fechaEntrega.dia,
  FECHA_ENTREGA_MES: fechaEntrega.mes,
  FECHA_ENTREGA_ANIO: fechaEntrega.anio,

  EXTRA: '',
  GRUA_CARGA: '',
  GRUA_DESCARGA: '',
  AUTOELEVADOR: '',

  FLETE_LOCAL: '',
  KM_IDA: formatoKm(kmIda),
  KM_IDA_VUELTA: formatoKm(kmIdaYVuelta),
  VEHICULO: primerValor(f['Patente (from flota)']),
  CHOFER: '',

  KM_TOTALES: '',
  KM_X2: '',
  TARIFA_KM: '',
  FLETE_CALC: '',

  FLETE: formatoMonto(f['Valor de Flete']),
  RIGGING: formatoMonto(f['Valor de Rigging']),
  ADICIONALES: formatoMonto(adicionales),

  TOTAL_PRESUPUESTO: formatoMonto(f['Valor Total'])
};

return [{ json: datos }];
